<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Storage};
use App\Models\{User,Service,Faq,PublicPage,Review,Inquiry,ClientStory,Media,Post};
use App\Services\{PublicSubmissions,ServiceEditor,WebsiteSettings,PageRegistry,CentreSchema};
class CentreReleaseTest extends TestCase {
 use RefreshDatabase;
 private function staff($role='administrator'):User{return User::factory()->create(['role'=>$role,'active'=>true]);}
 private function token():array{$this->get('/contact')->assertOk();$id=(string)\Illuminate\Support\Str::uuid();return ['submission_key'=>$id,'form_signature'=>hash_hmac('sha256',$id.'|'.session()->getId(),config('app.key'))];}
 private function inquiryData($source='consultation_form'):array{return $this->token()+['full_name'=>'Isolated Test Person','email'=>'isolated@outlook.example','mobile'=>'9920390000','country_code'=>'+91','interest'=>'Mental Health','session_preference'=>'No preference / Help me decide','contact_method'=>'email','message'=>'Isolated private test message','consent'=>1,'source'=>$source];}
 private function serviceData(Service $s,array $extra=[]):array{return array_merge(['name'=>$s->name,'slug'=>$s->slug,'summary'=>$s->summary,'body_html'=>$s->body_html,'display_order'=>0,'status'=>'draft','schema_mode'=>'automatic','version'=>$s->version],$extra);}
 public function test_real_seed_brand_contact_services_and_empty_feedback():void{$this->assertDatabaseCount('services',3);$this->assertDatabaseCount('reviews',0);$this->assertDatabaseCount('client_stories',0);$r=$this->get('/');$r->assertOk()->assertSee('Vidya Counseling Centre')->assertSee('vidyacounsellingcenter@gmail.com')->assertSee('https://wa.me/919920392160',false)->assertSee('All rights reserved by')->assertSee('https://hiteshahire.in',false)->assertDontSee('Vidya Counselling Centre')->assertDontSee('AggregateRating')->assertDontSee('FAQPage');$this->assertSame('Vidya Counseling Centre',app(WebsiteSettings::class)->get('brand_name'));}
 public function test_every_public_page_and_service_renders():void{foreach(['/','/services','/our-story','/reviews','/client-stories','/contact','/privacy','/blog','/sitemap.xml'] as $path)$this->get($path)->assertOk();foreach(Service::all() as $s)$this->get('/services/'.$s->slug)->assertOk()->assertSee($s->name)->assertSee('/contact?service='.$s->id,false);$this->get('/register')->assertNotFound();}
 public function test_owner_screens_and_empty_states_render():void{$this->actingAs($this->staff());foreach(['/admin/services','/admin/services/create','/admin/services/1','/admin/services/1/edit','/admin/services/1/preview','/admin/stories','/admin/stories/create','/admin/reviews','/admin/reviews/create','/admin/faqs','/admin/faqs/create','/admin/inquiries','/admin/website','/admin/faqs/draft-helper?page_id=1'] as $path)$this->get($path)->assertOk();$this->get('/admin/services/1/preview')->assertHeader('X-Robots-Tag','noindex, nofollow, noarchive');}
 public function test_editor_permissions_default_private_denial_and_explicit_grant():void{$u=$this->staff('editor');$this->actingAs($u);foreach(['/admin/stories','/admin/reviews','/admin/website','/admin/inquiries'] as $path)$this->get($path)->assertForbidden();foreach(['/admin/services','/admin/faqs','/admin/blogs'] as $path)$this->get($path)->assertOk();$u->forceFill(['can_manage_inquiries'=>true])->save();$this->get('/admin/inquiries')->assertOk();$this->put('/admin/website',[])->assertForbidden();}
 public function test_guest_write_endpoints_do_not_bypass_permissions():void{foreach(['/admin/services','/admin/stories','/admin/reviews','/admin/faqs','/admin/faqs/draft-helper'] as $path)$this->post($path,[])->assertRedirect('/login');$this->get('/admin/inquiries')->assertRedirect('/login');}
 public function test_both_inquiry_paths_persist_encrypted_and_not_appointments():void{foreach(['consultation_form','lets_talk'] as $source){$d=$this->inquiryData($source);$this->postJson('/consultation',$d)->assertCreated()->assertSee('not a confirmed appointment');}$this->assertDatabaseCount('inquiries',2);$i=Inquiry::first();$this->assertSame('+919920390000',$i->mobile);$raw=DB::table('inquiries')->first();foreach(['full_name','email','mobile','message'] as $key)$this->assertNotSame($i->$key,$raw->$key);$this->assertSame('new',$i->status);$this->assertNotNull($i->consented_at);$this->assertStringNotContainsString('private test',json_encode($i));$this->get('/')->assertDontSee('Isolated Test Person')->assertDontSee('isolated@outlook.example');$this->assertFalse(\Illuminate\Support\Facades\Schema::hasTable('appointments'));}
 public function test_inquiry_retries_are_idempotent_and_signature_is_bound_to_session():void{$d=$this->inquiryData();$this->postJson('/consultation',$d)->assertCreated();$this->postJson('/consultation',$d)->assertCreated();$d['submission_key']=(string)\Illuminate\Support\Str::uuid();$d['form_signature']=hash_hmac('sha256',$d['submission_key'].'|'.session()->getId(),config('app.key'));$this->postJson('/consultation',$d)->assertCreated();$this->assertDatabaseCount('inquiries',1);$d['form_signature']=str_repeat('0',64);$this->postJson('/consultation',$d)->assertStatus(419);}
 public function test_inquiry_validation_no_sensitive_flash_honeypot_and_throttle():void{$d=$this->inquiryData();$this->postJson('/consultation',array_merge($d,['consent'=>0,'interest'=>'Career']))->assertUnprocessable()->assertJsonValidationErrors(['consent','interest']);$this->post('/consultation',array_merge($d,['email'=>'bad']))->assertSessionHasErrors('email')->assertSessionMissing('_old_input');$this->postJson('/consultation',array_merge($d,['website'=>'spam']))->assertUnprocessable();$this->postJson('/consultation',array_merge($d,['session_preference'=>'Unsupported']))->assertUnprocessable();$this->postJson('/consultation',array_merge($d,['mobile'=>'abc']))->assertUnprocessable();$this->postJson('/consultation',$d)->assertStatus(429);$this->assertDatabaseCount('inquiries',0);}
 public function test_followups_encryption_permission_archive_restore_redaction():void{$this->postJson('/consultation',$this->inquiryData())->assertCreated();$i=Inquiry::first();$editor=$this->staff('editor');$this->actingAs($editor)->get('/admin/inquiries/'.$i->id)->assertForbidden();$admin=$this->staff();$this->actingAs($admin);$this->put('/admin/inquiries/'.$i->id,['status'=>'contacted','assigned_to'=>$editor->id])->assertStatus(422);$this->put('/admin/inquiries/'.$i->id,['status'=>'contacted','assigned_to'=>$admin->id,'note'=>'Isolated private note'])->assertRedirect();$this->assertNotNull($i->fresh()->contacted_at);$this->assertNotSame('Isolated private note',DB::table('inquiry_followups')->value('note'));$this->get('/admin/inquiries/'.$i->id)->assertOk()->assertHeader('Cache-Control','no-store, private');$this->delete('/admin/inquiries/'.$i->id)->assertRedirect();$this->assertSoftDeleted('inquiries',['id'=>$i->id]);$this->post('/admin/inquiries/'.$i->id.'/restore')->assertRedirect();$this->post('/admin/inquiries/'.$i->id.'/redact',['confirm'=>'REDACT'])->assertRedirect();$this->assertSame('[redacted]',$i->fresh()->email);$this->assertNull($i->followups()->first()->note);$this->assertStringNotContainsString('Isolated',DB::table('activities')->pluck('subject')->join(' '));}
 private function reviewData():array{return $this->token()+['anonymous'=>1,'email'=>'review@outlook.example','review_text'=>'Isolated genuine review text for moderation testing.','rating'=>4,'publication_consent'=>1];}
 public function test_review_pending_private_email_idempotency_and_public_consent_gate():void{$d=$this->reviewData();$this->postJson('/reviews',$d)->assertCreated();$this->postJson('/reviews',$d)->assertCreated();$this->assertDatabaseCount('reviews',1);$r=Review::first();$this->assertSame('pending',$r->status);$this->assertNotSame($r->email,DB::table('reviews')->value('email'));$this->get('/reviews')->assertDontSee($r->original_text);$r->update(['status'=>'approved']);$this->get('/reviews')->assertSee($r->original_text)->assertSee('Anonymous reviewer')->assertDontSee($r->email)->assertDontSee('AggregateRating');$r->update(['publication_consent'=>false]);$this->get('/reviews')->assertDontSee($r->original_text);}
 public function test_review_validation_plain_text_consent_and_throttle():void{$d=$this->reviewData();$this->postJson('/reviews',array_merge($d,['publication_consent'=>0]))->assertUnprocessable();$this->postJson('/reviews',array_merge($d,['review_text'=>'<script>alert(1)</script>']))->assertUnprocessable();$this->postJson('/reviews',array_merge($d,['rating'=>6,'website'=>'spam']))->assertUnprocessable();$this->postJson('/reviews',$d)->assertStatus(429);$this->assertDatabaseCount('reviews',0);}
 public function test_review_admin_preserves_original_and_restore_is_pending():void{$this->postJson('/reviews',$this->reviewData());$review=Review::first();$this->actingAs($this->staff());$d=['display_name'=>'Approved pseudonym','anonymous'=>1,'email'=>$review->email,'public_text'=>'Privacy edited wording.','status'=>'approved','publication_consent'=>1,'consented_at'=>now()->timezone('Asia/Kolkata')->format('Y-m-d\TH:i'),'featured'=>1,'display_order'=>2];$this->put('/admin/reviews/'.$review->id,$d)->assertRedirect();$this->assertNotSame($review->fresh()->original_text,$review->fresh()->public_text);$this->assertNotNull($review->fresh()->moderator_id);$this->get('/admin/reviews/'.$review->id.'/edit')->assertOk();$this->delete('/admin/reviews/'.$review->id)->assertRedirect();$this->post('/admin/reviews/'.$review->id.'/restore')->assertRedirect();$this->assertSame('pending',$review->fresh()->status);$this->get('/reviews')->assertDontSee('Privacy edited wording.');}
 public function test_service_validation_sanitization_slug_redirect_archive_and_concurrency():void{$u=$this->staff('editor');$s=Service::first();$this->actingAs($u);$this->put('/admin/services/'.$s->id,$this->serviceData($s,['slug'=>'new-safe-service','status'=>'published','body_html'=>$s->body_html.'<script>alert(1)</script>']))->assertRedirect();$s->refresh();$this->assertStringNotContainsString('<script>',$s->body_html);$this->get('/services/career-education-counselling')->assertRedirect('/services/new-safe-service')->assertStatus(301);$page=PublicPage::where('reference','service:'.$s->id)->first();$this->assertSame('/services/new-safe-service',$page->path);$this->put('/admin/services/'.$s->id,$this->serviceData($s,['version'=>1]))->assertSessionHasErrors('version');$this->put('/admin/services/'.$s->id,$this->serviceData($s,['status'=>'published','fees'=>'Unverified fee']))->assertSessionHasErrors('offer_verified');$this->delete('/admin/services/'.$s->id)->assertRedirect();$this->get('/services/new-safe-service')->assertNotFound();$this->post('/admin/services/'.$s->id.'/restore')->assertRedirect();$this->assertSame('draft',$s->fresh()->status);$this->get('/services/new-safe-service')->assertNotFound();}
 public function test_service_schema_manual_rules_and_no_self_serving_stars():void{$s=Service::first();$schema=app(CentreSchema::class)->service($s->load('sections'));$text=json_encode($schema);$this->assertStringContainsString('ServiceChannel',$text);$this->assertStringNotContainsString('AggregateRating',$text);$this->assertStringNotContainsString('MedicalClinic',$text);$node=['@context'=>'https://schema.org','@type'=>'Service','name'=>$s->name,'url'=>$s->canonical];$this->assertIsArray(app(CentreSchema::class)->validateManual(json_encode($node),$s));$this->expectException(\Illuminate\Validation\ValidationException::class);app(CentreSchema::class)->validateManual(json_encode([$node,$node]),$s);}
 public function test_faq_shared_assignments_order_archived_visibility_and_canonical_schema():void{$this->actingAs($this->staff('editor'));$home=PublicPage::where('reference','core:home')->first();$contact=PublicPage::where('reference','core:contact')->first();$this->post('/admin/faqs',['question'=>'An isolated shared question?','answer_html'=>'<p>An accurate shared answer.</p><script>alert(1)</script>','status'=>'published','pages'=>[$home->id,$contact->id],'orders'=>[$home->id=>2,$contact->id=>1],'schema_page_id'=>$home->id])->assertRedirect();$f=Faq::first();$this->get('/admin/faqs/'.$f->id.'/edit')->assertOk();$this->get('/')->assertSee($f->question)->assertDontSee('FAQPage');$this->get('/contact')->assertSee($f->question);app(WebsiteSettings::class)->save(['faq_schema_enabled'=>1]);$this->get('/')->assertSee('FAQPage');$this->get('/contact')->assertDontSee('FAQPage');$this->delete('/admin/faqs/'.$f->id)->assertRedirect();$this->get('/')->assertDontSee($f->question);$this->post('/admin/faqs/'.$f->id.'/restore')->assertRedirect();$this->assertSame('draft',$f->fresh()->status);$this->assertCount(2,$f->pages);}
 public function test_faq_registry_tracks_slug_without_losing_assignment_and_helper_drafts_only():void{$s=Service::first();$page=PublicPage::where('reference','service:'.$s->id)->first();$faq=Faq::create(['question'=>'Shared question','question_key'=>app(PageRegistry::class)->questionKey('Shared question'),'answer_html'=>'<p>Actual answer.</p>','status'=>'published']);$faq->pages()->attach($page->id);$s->slug='changed-url';$s->save();$this->assertSame($page->id,PublicPage::where('path','/services/changed-url')->value('id'));$this->assertCount(1,$faq->fresh()->pages);$this->actingAs($this->staff('editor'));$this->get('/admin/faqs/draft-helper?page_id='.$page->id)->assertOk()->assertSee('Template-based');$this->post('/admin/faqs/draft-helper',['page_id'=>$page->id,'selected'=>[0],'suggestions'=>[['question'=>'A new draft question?','answer'=>'A draft answer.']]])->assertRedirect();$this->assertDatabaseHas('faqs',['question'=>'A new draft question?','status'=>'draft']);$this->get('/services/changed-url')->assertDontSee('A new draft question?');}
 public function test_story_consent_identity_and_media_gating():void{$this->actingAs($this->staff());$d=['title'=>'Isolated consent case','quotation'=>'Authentic Counselling feedback.','anonymous'=>1,'source_type'=>'written','display_order'=>0,'status'=>'published','consent_status'=>'pending'];$this->post('/admin/stories',$d)->assertSessionHasErrors('consent_status');$d['consent_status']='approved';$d['consented_at']=now()->timezone('Asia/Kolkata')->format('Y-m-d\TH:i');$d['private_notes']='Isolated private permission reference';$this->post('/admin/stories',$d)->assertRedirect();$story=ClientStory::first();$this->get('/admin/stories/'.$story->id.'/edit')->assertOk();$this->assertNotSame($story->private_notes,DB::table('client_stories')->value('private_notes'));$this->get('/client-stories')->assertSee('Authentic Counselling feedback.')->assertSee('Anonymous client')->assertDontSee($d['private_notes']);$story->update(['consent_status'=>'withdrawn']);$this->get('/client-stories')->assertDontSee($story->quotation);}
 public function test_settings_allowlist_safe_story_and_unverified_shortcuts_hidden():void{$s=app(WebsiteSettings::class);$s->save(['whatsapp_verified'=>0,'not_a_setting'=>'secret']);$this->assertDatabaseMissing('site_settings',['key'=>'not_a_setting']);$this->get('/')->assertDontSee('https://wa.me/',false);$this->assertSame('vidyacounsellingcenter@gmail.com',$s->get('email'));$this->assertSame('', $s->get('opening_hours'));$this->assertSame('', $s->get('founder_media_id'));}
}
